import { makeCmaQuestions, type CmaQuestionSpec } from "@/data/cma-question-factory";
import type { CmaStudyUnit } from "@/data/cma-topics";

/** Original bilingual applications for the supplied 2024 outlines; source MCQs remain separate. */
const rows: (readonly [CmaStudyUnit, ...CmaQuestionSpec])[] = [
  [15,"cost-gap","su15-variance-overview","intermediate","تكلفة فعلية 13,000 مقابل معياري مسموح 12,000؛ كيف يصنف الفرق؟","Actual cost is 13,000 versus allowed standard cost 12,000. Classify the difference.",["1,000 غير مواتٍ","1,000 مواتٍ","25,000 غير مواتٍ","صفر"],["1,000 unfavorable","1,000 favorable","25,000 unfavorable","Zero"],0,"زيادة التكلفة 1,000 تقلل الربح. المواتي يعكس اتجاه التكلفة، و25,000 يجمع القيمتين، وصفر يهمل الاختلاف.","Actual exceeds allowed by 1,000, reducing income. Favorable reverses the cost effect; 25,000 adds the amounts; zero ignores the gap."],
  [15,"exception-priority","su15-variance-overview","intermediate","أي فرق أولى بالتحقيق وفق الإدارة بالاستثناء؟","Which variance warrants priority under management by exception?",["انحراف صغير عارض","انحراف كبير ومتكرر وقابل للتحكم","كل فرق مواتٍ فقط","أصغر فرق نسبي"],["One small isolated gap","A large recurring controllable gap","Only favorable gaps","The smallest relative gap"],1,"الأهمية والتكرار وقابلية المعالجة ترفع الأولوية؛ بقية الخيارات تهمل خطرًا جوهريًا أو تتبع اتجاهًا محاسبيًا فقط.","Magnitude, recurrence and actionability drive priority; the others ignore material risk or focus on accounting signs alone."],
  [15,"cheap-material-quality","su15-variance-overview","hard","انخفض سعر المادة لكن زادت الخردة وشكاوى العملاء؛ ما الاستنتاج المهني؟","Material price falls while scrap and customer complaints rise. What is the best interpretation?",["الوفر يثبت تحسنًا صافيًا","اربط فرق السعر بكمية الاستخدام والجودة","حمّل التسويق كل الفرق","احذف معيار الخردة"],["Savings prove net improvement","Link price to usage and quality","Charge all variance to marketing","Drop scrap standards"],1,"قد يخلق شراء الأرخص كلفة إعادة عمل وضمان أعلى؛ افحص الأثر الكلي وقرار المورد. البدائل تتجاهل ترابط الأداء.","A cheaper input can increase rework and warranty; assess total cost and sourcing. The alternatives ignore linked performance."],
  [15,"variance-reconciliation","su15-variance-overview","intermediate","تكلفة معيارية 20,000 وفعلية 19,200؛ ما أثر الفرق على الربح مع ثبات بقية العوامل؟","Standard cost is 20,000 and actual is 19,200. With everything else unchanged, what is the profit effect?",["800 انخفاض","800 ارتفاع","19,200 ارتفاع","لا أثر"],["Down 800","Up 800","Up 19,200","No effect"],1,"انخفاض التكلفة 800 يرفع الربح 800؛ الخيار الأول يعكس الأثر، والبقية لا تقيس الفرق الصحيح.","Cost is 800 below standard, raising income by 800. The other answers reverse or ignore the difference."],

  [15,"flex-cost","su15-flexible-variance","hard","تكلفة متغيرة 6 للوحدة وثابتة 5,000. عند إنتاج 800 وحدة، ما التكلفة المرنة؟","Variable cost is 6/unit and fixed cost 5,000. At 800 units, what is flexible-budget cost?",["4,800","9,800","10,800","5,000"],["4,800","9,800","10,800","5,000"],1,"6×800+5,000=9,800؛ 4,800 يهمل الثابت، و5,000 يهمل المتغير، و10,800 يغير المقدار دون أساس.","6×800+5,000=9,800. The other figures omit one component or use an unsupported adjustment."],
  [15,"volume-income","su15-flexible-variance","hard","الخطة 1,000 وحدة بهامش معياري 20؛ بيع فعلي 900 وحدة. ما فرق حجم المساهمة؟","Plan 1,000 units at standard contribution 20; actual units sold 900. Find the contribution-volume variance.",["2,000 غير مواتٍ","2,000 مواتٍ","18,000 غير مواتٍ","20,000 غير مواتٍ"],["2,000 unfavorable","2,000 favorable","18,000 unfavorable","20,000 unfavorable"],0,"(900−1,000)×20=2,000 غير مواتٍ؛ 18,000 مساهمة المرنة و20,000 المخططة لا يمثلان الفرق.","(900−1,000)×20 is 2,000 unfavorable; 18,000 and 20,000 are contribution levels, not their gap."],
  [15,"performance-income","su15-flexible-variance","hard","دخل مرن 10,000 ودخل فعلي 9,200؛ ما فرق الأداء؟","Flexible operating income is 10,000 and actual is 9,200. What is the performance variance?",["800 مواتٍ","800 غير مواتٍ","19,200 غير مواتٍ","صفر"],["800 favorable","800 unfavorable","19,200 unfavorable","Zero"],1,"الفعل أقل من المرن 800 فتتراجع الأرباح؛ 19,200 جمع للقيم وليس انحرافًا.","Actual income is 800 below flexible income, unfavorable. Adding the figures is not a variance."],
  [15,"fixed-flex","su15-flexible-variance","intermediate","ضمن المدى الملائم، خُطط مصروف ثابت 8,000 ثم زاد الإنتاج 10%. ما قيمته في الموازنة المرنة؟","Within the relevant range, fixed cost is budgeted at 8,000 and output rises 10%. What fixed amount belongs in the flexible budget?",["7,200","8,000","8,800","80,000"],["7,200","8,000","8,800","80,000"],1,"يظل الثابت الكلي 8,000 ضمن المدى. ضربه أو خصمه بنسبة النشاط يخلط سلوك المتغير والثابت.","Total fixed cost remains 8,000 in the relevant range; scaling it with output confuses variable and fixed behavior."],

  [15,"material-price-used","su15-materials-variance","hard","استُخدم 1,080 كغ بسعر5.50 بدل معياري6. ما فرق السعر على المستخدم؟","1,080 kg were used at 5.50 rather than standard 6. Find usage-based material price variance.",["540 مواتٍ","540 غير مواتٍ","480 غير مواتٍ","6,000 مواتٍ"],["540 favorable","540 unfavorable","480 unfavorable","6,000 favorable"],0,"1,080×(5.50−6)=−540 أي مواتٍ؛ 480 يخص فرق كمية محتمل، و6,000 تكلفـة معيارية لكمية أخرى.","1,080×(5.50−6)=−540, favorable. The 480 and 6,000 confuse other quantities or cost totals."],
  [15,"material-usage","su15-materials-variance","hard","أنتجت 500 وحدة بمعيار2 كغ وسعر6؛ استُخدم1,080 كغ. كم فرق الكمية؟","500 units at 2 standard kg and 6/kg used 1,080 kg. What is material usage variance?",["80 غير مواتٍ","480 غير مواتٍ","480 مواتٍ","1,080 غير مواتٍ"],["80 unfavorable","480 unfavorable","480 favorable","1,080 unfavorable"],1,"المسموح1,000 كغ؛ 80 زائدة×6=480 غير مواتٍ. 80 كمية لا قيمة، والمواتي يعكس الإشارة.","Allowed is 1,000 kg; excess 80×6=480 unfavorable. Eighty is kilograms, not currency; favorable reverses the sign."],
  [15,"purchase-vs-use","su15-materials-variance","hard","اشتريت1,100 كغ بسعر7 بدل8 واستخدمت900. ما فرق سعر الشراء؟","Purchased 1,100 kg at 7 versus standard 8 and used 900. What is the purchase-price variance?",["900 مواتٍ","1,100 مواتٍ","200 مواتٍ","1,100 غير مواتٍ"],["900 favorable","1,100 favorable","200 favorable","1,100 unfavorable"],1,"على المشتريات1,100×(7−8)=1,100 مواتٍ. 900 يستخدم كمية الإنتاج؛ 200 فرق كميات الشراء والاستخدام.","Purchase-based price variance uses 1,100×(7−8)=1,100 favorable; 900 uses consumed quantity and 200 is the inventory quantity gap."],
  [15,"material-cost-bridge","su15-materials-variance","hard","مسموح1,000 كغ بسعر6، فعلي1,080 كغ بسعر5.50. ما فرق التكلفة الفعلية عن المسموحة؟","Allowed input is 1,000 kg at 6; actual use is 1,080 kg at 5.50. Find actual less allowed cost.",["60 مواتٍ","60 غير مواتٍ","480 غير مواتٍ","540 مواتٍ"],["60 favorable","60 unfavorable","480 unfavorable","540 favorable"],0,"الفعلي5,940 مقابل معيار6,000، أي60 مواتٍ؛ يساوي540 مواتٍ للسعر ناقص480 غير مواتٍ للاستخدام.","Actual 5,940 versus allowed 6,000 is 60 favorable; price 540 favorable offsets 480 unfavorable usage."],

  [15,"labor-rate","su15-labor-variance","hard","عمل فعلي 630 ساعة بتكلفة13,230 ومعيار أجر20. ما فرق معدل الأجر؟","Actual labor is 630 hours costing 13,230, with standard wage 20/hour. Find labor rate variance.",["630 غير مواتٍ","630 مواتٍ","600 غير مواتٍ","1,230 غير مواتٍ"],["630 unfavorable","630 favorable","600 unfavorable","1,230 unfavorable"],0,"المعدل الفعلي21؛ فرق المعدل630×(21−20)=630 غير مواتٍ. 600 فرق كفاءة في مثال مرتبط، و1,230 الإجمالي.","Actual rate is 21; rate variance 630×(21−20)=630 unfavorable. The others confuse efficiency or total labor gap."],
  [15,"labor-efficiency","su15-labor-variance","hard","الإنتاج400 وحدة بمعيار1.5 ساعة للوحدة، والعمل الفعلي630 ساعة، والأجر المعياري20. ما فرق الكفاءة؟","Output 400 units at 1.5 standard hours, actual labor 630 hours, standard rate 20. Find efficiency variance.",["600 غير مواتٍ","600 مواتٍ","630 غير مواتٍ","12,600 غير مواتٍ"],["600 unfavorable","600 favorable","630 unfavorable","12,600 unfavorable"],0,"المسموح600 ساعة؛ زيادة30×20=600 غير مواتٍ. 630 قد يكون فرق الأجر إن كان فعليًا21؛ 12,600 تكلفة الساعات الفعلية بالمعيار.","Allowed hours 600; excess 30×20=600 unfavorable. Other figures confuse rate or total standard-price cost."],
  [15,"labor-total","su15-labor-variance","hard","مسموح600 ساعة×20، فعلي630 ساعة×21. ما الفرق الكلي؟","Allowed labor is 600 hours×20 and actual 630 hours×21. What is the total labor variance?",["1,230 غير مواتٍ","1,230 مواتٍ","600 غير مواتٍ","630 غير مواتٍ"],["1,230 unfavorable","1,230 favorable","600 unfavorable","630 unfavorable"],0,"الفعلي13,230−المسموح12,000=1,230 غير مواتٍ؛ 600 و630 جزءا الكفاءة والمعدل فقط.","Actual 13,230 less allowed 12,000 is 1,230 unfavorable; 600 and 630 are individual components."],
  [15,"labor-quality","su15-labor-variance","intermediate","انخفض أجر الساعة لكن ارتفعت ساعات إعادة العمل. ما التحليل الأنسب؟","The hourly wage falls but rework hours increase. What is the sound interpretation?",["المعدل المواتي يحسم النجاح","حلل المعدل والكفاءة والجودة معًا","إلغاء معيار ساعات الإنتاج","تسجيل إعادة العمل كإيراد"],["Favorable rate proves success","Assess rate, efficiency and quality together","Remove hour standard","Record rework as revenue"],1,"وفـر الأجر قد يُمحى بساعات وهدر وضمان إضافيين؛ بقية الاختيارات تعزل رقمًا أو تقترح معالجة غير صحيحة.","Wage saving may be outweighed by extra hours, scrap or warranty; the other choices isolate one metric or misstate accounting."],

  [15,"sms-price","su15-mix-yield","hard","مزيج معياري A بنسبة60% بسعر10 وB بنسبة40% بسعر5. ما متوسط السعر المعياري؟","Standard mix: A 60% at 10, B 40% at 5. Find weighted standard input price.",["7.5","8","15","5"],["7.5","8","15","5"],1,"0.6×10+0.4×5=8؛ 7.5 متوسط المزيج الفعلي المتساوي، و15 جمع السعرين دون أوزان.","0.6×10+0.4×5=8; 7.5 corresponds to a 50/50 mix, while 15 adds unweighted prices."],
  [15,"actual-mix-standard-price","su15-mix-yield","hard","استُخدم100 كغ، 50 كغ من A معياره10 و50 من B معياره5. ما تكلفة المزيج الفعلي بالأسعار المعيارية؟","100 kg used: 50 kg A at standard 10 and 50 kg B at standard 5. Find actual-mix cost at standards.",["500","750","800","1,000"],["500","750","800","1,000"],1,"50×10+50×5=750. 800 تكلفة100 كغ بالمزيج المعياري60/40، و500 و1,000 يهملان صنفًا.","50×10+50×5=750. Eight hundred uses standard composition; 500 and 1,000 omit a material."],
  [15,"mix-component","su15-mix-yield","hard","متوسط السعر المعياري للمزيج8 والفعلي بالأسعار المعيارية7.5؛ مجموع الاستخدام100 كغ. ما فرق المزيج؟","SMSP is 8 and AMSP at standard prices 7.5; total actual input 100 kg. Find mix variance.",["50 مواتٍ","50 غير مواتٍ","80 غير مواتٍ","750 مواتٍ"],["50 favorable","50 unfavorable","80 unfavorable","750 favorable"],0,"100×(7.5−8)=−50 تكلفة، أي50 مواتٍ. 80 فرق مردود محتمل، و750 تكلفة لا فرق.","100×(7.5−8)=−50 cost, hence 50 favorable. Eighty is a possible yield gap; 750 is cost, not variance."],
  [15,"yield-component","su15-mix-yield","hard","كمية فعلية100 كغ ومسموح90 كغ ومتوسط سعر المزيج المعياري8. ما فرق المردود؟","Actual input is 100 kg versus 90 allowed, with SMSP 8. Find yield variance.",["10 غير مواتٍ","80 غير مواتٍ","80 مواتٍ","90 غير مواتٍ"],["10 unfavorable","80 unfavorable","80 favorable","90 unfavorable"],1,"الزيادة10 كغ×8=80 غير مواتٍ. 10 كمية لا مبلغ، و80 مواتٍ يعكس تكلفة الزيادة.","Extra 10 kg×8=80 unfavorable. Ten is a quantity; favorable reverses the excess cost."],

  [15,"voh-spending","su15-overhead-variance","hard","صناعي متغير فعلي13,200 على2,200 ساعة، معياره5 للساعة. ما فرق الإنفاق؟","Actual variable overhead is 13,200 over 2,200 hours; standard rate is 5/hour. Find spending variance.",["2,200 غير مواتٍ","1,000 غير مواتٍ","3,200 غير مواتٍ","2,200 مواتٍ"],["2,200 unfavorable","1,000 unfavorable","3,200 unfavorable","2,200 favorable"],0,"المعدل الفعلي6؛ 2,200×(6−5)=2,200 غير مواتٍ. 1,000 فرق كفاءة إذا المسموح2,000؛ 3,200 الإجمالي.","Actual rate 6; 2,200×(6−5)=2,200 unfavorable. Other figures are efficiency or total under additional assumptions."],
  [15,"voh-efficiency","su15-overhead-variance","hard","ساعة محرك فعلية2,200 ومسموحة2,000، ومعدل صناعي متغير معياري5. ما فرق الكفاءة؟","Actual overhead driver hours are 2,200 versus 2,000 allowed, standard variable rate 5. Find efficiency variance.",["1,000 غير مواتٍ","1,000 مواتٍ","2,200 غير مواتٍ","10,000 غير مواتٍ"],["1,000 unfavorable","1,000 favorable","2,200 unfavorable","10,000 unfavorable"],0,"(2,200−2,000)×5=1,000 غير مواتٍ. 2,200 قد يمثل فرق إنفاق في بيانات أخرى؛ 10,000 مبلغ مرن.","(2,200−2,000)×5=1,000 unfavorable. The other figures confuse spending or flexible allowance."],
  [15,"foh-spending","su15-overhead-variance","hard","صناعي ثابت مخطط24,000 وفعلي23,500. ما فرق الإنفاق؟","Budgeted fixed overhead is 24,000 and actual 23,500. Find spending variance.",["500 مواتٍ","500 غير مواتٍ","1,600 غير مواتٍ","لا يمكن دون ساعات فعلية"],["500 favorable","500 unfavorable","1,600 unfavorable","Cannot determine without actual hours"],0,"الفعلي أقل500 فيكون مواتيًا؛ فرق إنفاق الثابت لا يتطلب ساعات، و1,600 قد يمثل فرق حجم منفصلًا.","Actual fixed spending is 500 below budget, favorable. Fixed spending variance needs no actual hours; 1,600 could be a separate volume gap."],
  [15,"foh-volume","su15-overhead-variance","hard","ثابت مخطط24,000 لمقام3,000 ساعة؛ المسموح للناتج2,800 ساعة. ما فرق حجم الإنتاج؟","Fixed overhead budget is 24,000 on 3,000 denominator hours; actual-output allowance 2,800 hours. Find volume variance.",["1,600 غير مواتٍ","1,600 مواتٍ","500 مواتٍ","24,000 غير مواتٍ"],["1,600 unfavorable","1,600 favorable","500 favorable","24,000 unfavorable"],0,"المعدل8؛ المطبق22,400؛ المخطط24,000 ناقص المطبق=1,600 غير مواتٍ. 500 فرق إنفاق مستقل.","Rate 8, applied 22,400; budget less applied is 1,600 unfavorable. Five hundred is a separate spending gap."],

  [15,"complete-total","su15-comprehensive","hard","فروق غير مواتية للمواد480 والعمل1,230 والمتغير350 والثابت500. كم إجمالي فروق التكلفة؟","Unfavorable variances: materials 480, labor 1,230, variable overhead 350, fixed overhead 500. Total?",["1,900 غير مواتٍ","2,560 غير مواتٍ","2,560 مواتٍ","45,560 غير مواتٍ"],["1,900 unfavorable","2,560 unfavorable","2,560 favorable","45,560 unfavorable"],1,"اجمع 480+1,230+350+500=2,560 غير مواتٍ؛ 1,900 يستبعد العمل، و45,560 قد يمثل التكلفة الفعلية.","480+1,230+350+500=2,560 unfavorable. Other options omit a component or confuse actual cost with variance."],
  [15,"complete-allowed","su15-comprehensive","hard","إجمالي تكلفة فعلية45,560 وفرق كلي2,560 غير مواتٍ. كم التكلفة المعيارية المسموحة؟","Actual total cost is 45,560 with a 2,560 unfavorable gap. Find allowed standard cost.",["43,000","48,120","45,560","2,560"],["43,000","48,120","45,560","2,560"],0,"المسموح=الفعلي−الزيادة=43,000؛ 48,120 يضيف الفرق ثانية، و2,560 فرق لا أساس تكلفة.","Allowed =45,560−2,560=43,000. The other values add the gap or report a variance rather than a cost base."],
  [15,"complete-reconcile","su15-comprehensive","intermediate","في جدول تكلفة فعلي/وسيط/معياري، ما الفرق بين AQ×SP وSQ×SP؟","In an actual/bridge/allowed input table, what does AQ×SP less SQ×SP isolate?",["فرق سعر","فرق كمية بالسعر المعياري","فرق حجم مبيعات","فرق إنفاق ثابت"],["Price variance","Quantity variance at standard price","Sales volume variance","Fixed spending variance"],1,"السعر المعياري ثابت في القيمتين فتفسر الكمية الفرق؛ السعر يختلف عند مقارنة AQ×AP مع AQ×SP.","Standard price is held fixed, isolating quantity; price changes in AQ×AP versus AQ×SP."],
  [15,"complete-inventory","su15-comprehensive","hard","فرق سعر شراء محسوب على1,000 كغ لكن الإنتاج استخدم800. ما اللازم قبل جمعه مع فرق كمية الإنتاج لتسوية تكلفته؟","Purchase-price variance uses 1,000 kg but production consumed 800. What must be addressed before summing it with usage variance for production cost?",["لا شيء","سوِّ أثر 200 كغ على المخزون","اضرب فرق الكمية في سعر البيع","ألغِ فرق السعر"],["Nothing","Reconcile the 200 kg inventory effect","Use selling price for usage","Delete the price variance"],1,"فرق الشراء على كامل 1,000 يشمل200 كغ غير مستخدمة؛ لا يطابق جسر تكلفة الإنتاج حتى تفصل المخزون. بقية الخيارات تتجاهل اختلاف الأساس.","The purchase variance includes 200 kg not consumed; isolate inventory before comparing with current production cost. Other options ignore the basis mismatch."],

  [15,"sales-price","su15-sales-variance","hard","باعت منشأة1,100 وحدة بسعر29 بدل معيار30. ما فرق سعر المبيعات؟","Actual sales 1,100 units at 29 instead of standard 30. Find sales price variance.",["1,100 غير مواتٍ","1,100 مواتٍ","100 مواتٍ","29,000 غير مواتٍ"],["1,100 unfavorable","1,100 favorable","100 favorable","29,000 unfavorable"],0,"1,100×(29−30)=1,100 غير مواتٍ؛ 100 قد يكون فرقًا صافيًا مع حجم مختلف، وليس فرق السعر.","1,100×(29−30) is 1,100 unfavorable; 100 may be a net effect after volume, not the isolated price."],
  [15,"sales-volume","su15-sales-variance","hard","مبيعات مخططة1,000 وفعلية1,100 وهامش معياري12. ما فرق حجم المساهمة؟","Budget sales 1,000 units, actual 1,100, standard contribution 12. Find sales-volume effect.",["1,200 مواتٍ","1,200 غير مواتٍ","3,000 مواتٍ","100 مواتٍ"],["1,200 favorable","1,200 unfavorable","3,000 favorable","100 favorable"],0,"(1,100−1,000)×12=1,200 مواتٍ؛ 100 هو فرق وحدات، و3,000 يستخدم السعر لا هامش المساهمة.","100 extra units×12 margin=1,200 favorable; 100 is units and 3,000 uses selling price rather than margin."],
  [15,"sales-mix","su15-sales-variance","hard","بيع فعلي520 وحدة؛ المزيج المعياري60% من A، والفعلي260 وحدة A وهامشه المعياري3. ما فرق مزيج A؟","Actual total sales 520; standard mix is 60% A, actual A units 260, standard A margin 3. Find A's mix component.",["156 غير مواتٍ","156 مواتٍ","36 مواتٍ","52 غير مواتٍ"],["156 unfavorable","156 favorable","36 favorable","52 unfavorable"],0,"وحدات A المتوقعة بالمزيج312؛ (260−312)×3=156 غير مواتٍ؛ 36 يخلط فرق الكمية.","Expected A at standard mix is 312; (260−312)×3=156 unfavorable. The 36 alternative confuses total sales quantity."],
  [15,"market-size","su15-sales-variance","hard","حصة مخططة20%، سوق مخطط1,000 وحدة وفعلية1,100، هامش مساهمة معياري10. ما أثر حجم السوق؟","Budget share is 20%, market grows from 1,000 to 1,100 units, standard margin 10. Find market-size variance.",["200 مواتٍ","100 مواتٍ","1,000 مواتٍ","200 غير مواتٍ"],["200 favorable","100 favorable","1,000 favorable","200 unfavorable"],0,"20%×(1,100−1,000)×10=200 مواتٍ؛ 100 فرق السوق قبل الحصة والهامش.","0.20×100 market growth×10 margin=200 favorable. One hundred is market-unit change before share and margin."],
  [16,"center-cost","su16-responsibility-centers","easy","قسم التنظيف لا يحدد أسعار الخدمة ولا يستثمر في الأصول، ويضبط مصروفاته. ما نوعه؟","A janitorial department controls expenses but not prices or invested assets. What center is it?",["تكلفة","إيراد","ربح","استثمار"],["Cost","Revenue","Profit","Investment"],0,"مسؤولية المدير المباشرة هي النفقة؛ الأنواع الأخرى تحتاج إيرادًا أو ربحًا أو رأس مال تحت القرار.","The manager directly controls spending; the other types require decision rights over revenue, profit or capital."],
  [16,"center-investment","su16-responsibility-centers","easy","مدير فرع يحدد الأسعار والمصروفات ومشتريات الآلات. إلى أي مركز تنتمي مسؤوليته؟","A branch manager controls pricing, expenses and equipment investment. Which center?",["تكلفة","إيراد","ربح فقط","استثمار"],["Cost","Revenue","Profit only","Investment"],3,"يشمل نطاقه ربحًا وأصولًا، فيصبح استثمارًا؛ مركز الربح لا يُقيّم على توظيف رأس المال.","The manager controls income and assets, making it an investment center; a profit center lacks capital authority."],
  [16,"common-rent","su16-responsibility-centers","intermediate","وُزع إيجار مقر الإدارة على الفروع رغم عدم استطاعة مدير الفرع تغييره. كيف يعرض تقييم المدير؟","Head-office rent is allocated to branches but local managers cannot change it. How should personal performance be shown?",["حمّله وحده بالانحراف","اعرض مساهمة قابلة للتحكم منفصلة عن التخصيص","احذف الإيجار من قوائم الشركة","ارفع الإيراد بدلًا من الإيجار"],["Assign full variance personally","Separate controllable contribution from allocation","Omit rent from company statements","Increase revenue to offset rent"],1,"التخصيص قد يلزم لتحليل الشركة لكنه ليس تحت قرار المدير؛ حذفه من قوائم الشركة أو تحميله له وحده كلاهما غير سليم.","Allocation may inform corporate economics but not local controllability. Neither omitting real company cost nor blaming the local manager is appropriate."],
  [16,"suboptimization","su16-responsibility-centers","intermediate","رفض قسم توريدًا داخليًا مفيدًا للشركة كي يحافظ على هامشه المقاس. ما اسم هذا السلوك؟","A division rejects a company-beneficial internal transfer to protect its measured margin. What is this?",["توافق الأهداف","تحسين محلي ضار بالمجموعة","تنويع مخاطر","رقابة وقائية"],["Goal congruence","Suboptimization","Risk diversification","Preventive control"],1,"يرفع مؤشر القسم على حساب الربح الكلي؛ هذا تحسين محلي لا توافق أهداف. الخيارات الأخرى لا تصف المفاضلة.","Segment optimization harms corporate value, the definition of suboptimization. The alternatives do not describe this conflict."],

  [16,"contribution","su16-cost-revenue-profit","hard","إيراد قسم180,000 وتكاليفه المتغيرة100,000. ما هامش المساهمة؟","Segment revenue is 180,000 and variable costs 100,000. Find contribution margin.",["40,000","55,000","80,000","180,000"],["40,000","55,000","80,000","180,000"],2,"180,000−100,000=80,000؛ 55,000 بعد ثابت مباشر محتمل، و40,000 بعد مصروف مشترك.","Revenue less variable cost is 80,000. Lower amounts would subtract additional fixed charges."],
  [16,"segment-margin","su16-cost-revenue-profit","hard","إيراد180,000 ومتغير100,000 وثابت مباشر25,000 ومشترك15,000. كم هامش القطاع؟","Revenue 180,000, variable 100,000, traceable fixed 25,000, common allocated 15,000. Find segment margin.",["40,000","55,000","80,000","95,000"],["40,000","55,000","80,000","95,000"],1,"المساهمة80,000 ناقص الثابت المباشر25,000=55,000؛ لا تخصم المشترك في هامش القطاع. 40,000 بعد التخصيص.","Contribution 80,000 less traceable fixed 25,000 is 55,000; common allocation is below segment margin."],
  [16,"reported-after-common","su16-cost-revenue-profit","hard","هامش قطاع55,000 وتخصيص مركزي15,000. ما الربح بعد التخصيص؟","Segment margin is 55,000 and central common allocation 15,000. What is profit after allocation?",["40,000","55,000","70,000","15,000"],["40,000","55,000","70,000","15,000"],0,"55,000−15,000=40,000؛ 55,000 قبل التخصيص، و70,000 يضيف نفقة.","55,000−15,000=40,000; 55,000 is before common allocation, and 70,000 incorrectly adds expense."],
  [16,"revenue-quality","su16-cost-revenue-profit","intermediate","ارتفعت مبيعات مركز إيراد مع خصومات كبيرة وتعثر تحصيل الذمم. ما المؤشرات المكملة؟","A revenue center raises sales through heavy discounts and weak collection. What else should management monitor?",["عدد الفواتير فقط","الهامش والتحصيل وجودة العملاء","إلغاء رقابة الائتمان","إجمالي الإيراد دون خصم"],["Only invoice count","Margin, collections and customer quality","Remove credit control","Gross revenue without discounts"],1,"المبيعات وحدها لا تضمن مساهمة أو نقدًا؛ الخيارات الأخرى تهمل السعر والمخاطر الائتمانية.","Revenue alone does not guarantee margin or cash; the other options ignore pricing and credit risk."],

  [16,"roi-basic","su16-investment-centers","hard","ربح تشغيل90,000 على أصول مستثمرة600,000. كم ROI؟","Operating profit is 90,000 on 600,000 invested assets. Find ROI.",["10%","15%","20%","60%"],["10%","15%","20%","60%"],1,"90,000÷600,000=15%. 10% قد يكون معدل مطلوب، وبقية النسب لا تتفق مع المقام.","90,000/600,000=15%; 10% might be a hurdle rate, not the measured return."],
  [16,"roi-dupont","su16-investment-centers","hard","مبيعات1,000,000 وربح100,000 وأصول500,000. كم هامش التشغيل ودوران الأصول وROI؟","Sales 1,000,000, profit 100,000, invested assets 500,000. Find margin, turnover and ROI.",["10% و2 و20%","20% و2 و10%","10% و0.5 و5%","20% و1 و20%"],["10%, 2, 20%","20%, 2, 10%","10%, 0.5, 5%","20%, 1, 20%"],0,"الهامش100,000÷1,000,000=10%؛ الدوران1,000,000÷500,000=2؛ العائد20%.","Margin 10%; turnover 2; their product is ROI 20%. Others reverse bases or omit the multiplication."],
  [16,"residual-income","su16-investment-centers","hard","ربح90,000 وأصول600,000 ومعدل عائد مطلوب10%. ما الدخل المتبقي؟","Operating income 90,000, invested assets 600,000, required return 10%. Find residual income.",["30,000","60,000","90,000","150,000"],["30,000","60,000","90,000","150,000"],0,"عبء رأس المال60,000؛ المتبقي90,000−60,000=30,000. 60,000 عبء لا دخل.","Capital charge is 60,000, leaving 90,000−60,000=30,000. Sixty thousand is the charge, not RI."],
  [16,"ri-new-project","su16-investment-centers","hard","مشروع يتطلب100,000 ويضيف دخل تشغيل12,000 ومعدل مطلوب10%. كم يضيف للدخل المتبقي؟","A project costs 100,000 and adds 12,000 income, with required return 10%. What incremental RI does it add?",["2,000","10,000","12,000","22,000"],["2,000","10,000","12,000","22,000"],0,"12,000−(100,000×10%)=2,000؛ 10,000 عبء رأس مال، و12,000 دخل قبل عبئه.","12,000−10,000 capital charge=2,000. The other choices report charge or income alone or add them."],

  [16,"bsc-finance","su16-balanced-scorecard","easy","في بطاقة الأداء، بأي منظور يصنف هامش التشغيل؟","Which balanced-scorecard perspective contains operating margin?",["المالي","العميل","العمليات الداخلية","التعلم والنمو"],["Financial","Customer","Internal process","Learning and growth"],0,"الهامش يقيس النتيجة المالية؛ بقية الزوايا تعنى بعملاء أو عمليات أو قدرات العاملين.","Operating margin is a financial outcome, not a customer, process or capability measure."],
  [16,"bsc-customer","su16-balanced-scorecard","easy","نسبة الاحتفاظ بالعملاء تنتمي أساسًا لأي منظور؟","Customer retention rate primarily belongs to which perspective?",["مالي","العميل","العمليات","التعلم"],["Financial","Customer","Internal process","Learning"],1,"الاحتفاظ يقيس علاقة العميل؛ قد يؤثر لاحقًا في الربح لكنه ليس بحد ذاته مقياسًا ماليًا.","Retention describes the customer relationship; it may lead to profit but is not itself a financial measure."],
  [16,"bsc-leading","su16-balanced-scorecard","intermediate","أي مؤشر قد يقود انخفاض عيوب الإنتاج مستقبلًا؟","Which measure could lead future reductions in production defects?",["ربح السنة السابقة","تدريب مشغلي الجودة واختبار المهارة","إجمالي التوزيعات","ضريبة دخل العام الماضي"],["Prior-year profit","Quality-operator training and assessed skill","Dividends","Last year's income tax"],1,"تنمية المهارة قد تحسن العملية لاحقًا؛ الربح والضرائب مؤشرات متأخرة لا تحدد مهارة التشغيل.","Skills can improve the process later; past financial results are lagging and do not measure operating capability."],
  [16,"bsc-gaming","su16-balanced-scorecard","intermediate","انخفض زمن المكالمة لكن زادت مكالمات إعادة فتح الشكاوى. ما التعديل الرقابي؟","Call duration falls but reopened complaints rise. What metric pairing helps?",["كافئ الزمن فقط","أضف الحل من أول اتصال ورضا العملاء","احذف سجل الشكاوى","احسب المبيعات فقط"],["Reward only speed","Track first-contact resolution and satisfaction","Delete complaint logs","Use sales alone"],1,"قياس السرعة منفردًا يشجع الإغلاق المبكر؛ الحل والرضا يوازنان جودة الخدمة. حذف البيانات يمنع التصحيح.","Speed alone rewards premature closure; resolution and satisfaction balance quality. Deleting complaints prevents learning."],

  [16,"transfer-idle-min","su16-transfer-pricing","hard","بائع داخلي لديه طاقة عاطلة، تكلفته الإضافية12 للوحدة ولا تكلفة نقل. ما الحد الأدنى الملائم؟","An internal seller has idle capacity and incremental cost 12/unit, with no extra transfer cost. Find its minimum relevant transfer price.",["12","20","25","37"],["12","20","25","37"],0,"الفرصة الضائعة صفر في الطاقة العاطلة؛ الحد الأدنى 12. سعر السوق 25 لا يلزم حدًا أدنى هنا.","There is no lost outside sale at idle capacity, so minimum is incremental cost 12; market price is not the minimum."],
  [16,"transfer-full-min","su16-transfer-pricing","hard","تكلفة متغيرة12 وسعر بيع خارجي25، والطاقة ممتلئة والبيع الخارجي سيتزاحم. ما حد البائع الأدنى؟","Variable cost 12, outside selling price 25, full capacity with displaced outside sale. Find seller minimum.",["12","13","25","37"],["12","13","25","37"],2,"مساهمة الفرصة25−12=13؛ الحد12+13=25. 37 يضيف السعر الكامل إلى التكلفة مرتين.","Lost contribution is 25−12=13; minimum 12+13=25. Thirty-seven double counts selling price."],
  [16,"transfer-range","su16-transfer-pricing","hard","تكلفة إضافية12 وطاقة عاطلة وبديل مشتري خارجي20. ما نطاق سعر مقبول للطرفين؟","Incremental cost 12, idle capacity, buyer outside option 20. What price range could both divisions accept?",["12–20","20–25","0–12","25–30"],["12–20","20–25","0–12","25–30"],0,"الحد الأدنى12 والحد الأقصى20؛ المجال يسمح بمساهمة للبائع وتكلفة لا تتجاوز البديل للمشتري.","Seller minimum is 12, buyer maximum 20. Other ranges violate seller or buyer incentives."],
  [16,"transfer-corporate","su16-transfer-pricing","hard","بديل الشراء الخارجي20، وتكلفة إنتاج داخلي إضافية12 مع طاقة عاطلة. ما وفر المجموعة للوحدة؟","An outside alternative is 20; internal incremental production costs 12 at idle capacity. Corporate saving per unit?",["8","12","20","32"],["8","12","20","32"],0,"20−12=8؛ سعر التحويل المحاسبي بين القسمين يلغى داخل المجموعة، فلا يدخل في الوفر.","20−12=8. Internal transfer price cancels for the consolidated firm and does not change this saving."],
  [17,"board-role","su17-governance","intermediate","من المسؤول أساسًا عن الإشراف على الإدارة والرقابة عبر مجلس الإدارة؟","Who principally oversees management and governance controls at board level?",["مجلس الإدارة","موظف المخزن","مورد الخدمة","عميل واحد"],["Board of directors","Warehouse clerk","Service vendor","One customer"],0,"المجلس يضع الإشراف والمساءلة؛ الإدارة تنفذ الضوابط اليومية. الأطراف الأخرى لا تملك دور حوكمة المجلس.","The board oversees accountability while management operates daily controls; the other parties lack this governance role."],
  [17,"audit-committee","su17-governance","intermediate","أي عمل أقرب لاختصاص لجنة المراجعة المستقلة؟","Which duty best fits an independent audit committee?",["إعداد كل فاتورة","الإشراف على التقارير واستقلال المدقق","اعتماد كل إذن مخزون","كتابة شيفرة ERP"],["Prepare every invoice","Oversee reporting and auditor independence","Approve each stock ticket","Code the ERP"],1,"الإشراف على التقرير والمدقق من دور اللجنة؛ التنفيذ والتسجيل اليومي مسؤولية الإدارة المختصة.","Reporting and auditor oversight belongs to the committee; daily processing and coding are operational management tasks."],
  [17,"outsourced-payroll","su17-governance","hard","عهدت منشأة الرواتب لمورد خارجي. من يظل مسؤولًا عن صحة أرقام الرواتب بقوائمها؟","A company outsources payroll. Who remains accountable for payroll amounts in its statements?",["المورد وحده","إدارة المنشأة","البنك وحده","لا أحد"],["Vendor alone","Entity management","Bank alone","Nobody"],1,"تعهيد المعالجة لا ينقل مسؤولية الإدارة عن تقريرها ورقابتها؛ تحتاج تأكيدات ومطابقة لخدمات المورد.","Outsourcing processing does not transfer management's reporting and control responsibility; it must oversee the provider."],
  [17,"policy-evidence","su17-governance","intermediate","سياسة مكافحة الاحتيال موقعة لكن لا أدلة اختبار أو تصحيح. ما التقييم؟","An antifraud policy is signed but has no test or remediation evidence. What conclusion follows?",["التوقيع يثبت التشغيل","اختبر التنفيذ ونتائج الاستثناءات","ألغ لجنة المراجعة","سجل السياسة أصلًا"],["Signature proves operation","Test operation and exception remediation","Remove the audit committee","Capitalize the policy"],1,"التصميم الورقي وحده لا يثبت التطبيق؛ يجب اختبار التشغيل وتتبع المعالجة. البدائل لا تقدم دليلاً.","A documented policy is not proof of operation; test performance and remediation. The other choices offer no evidence."],

  [17,"coso-components","su17-risk-controls","intermediate","أي مجموعة تمثل مكونات COSO الخمسة للرقابة الداخلية؟","Which set lists COSO's five internal-control components?",["البيئة والمخاطر والأنشطة والمعلومات والمتابعة","الربح والمبيعات والذمم والمخزون والنقد","التمويل والاستثمار والإيراد والعميل والضريبة","الدفتر والمخزن والرواتب والأصول والنظام"],["Environment, risk assessment, activities, information and monitoring","Profit, sales, receivables, stock, cash","Financing, investing, income, customer, tax","Ledger, warehouse, payroll, assets, system"],0,"هذه المكونات تترابط لتحقيق أهداف التشغيل والتقارير والامتثال؛ القوائم الأخرى بنود مالية أو نظم وليست إطار COSO.","These five linked components support operations, reporting and compliance; the others list accounts or systems."],
  [17,"inherent-control","su17-risk-controls","intermediate","ما المقصود بالخطر الملازم قبل تنفيذ ضابط المنع؟","What is inherent risk in a process?",["الخطر قبل أثر الضوابط","الخطر بعد كل التصحيحات فقط","تكلفة المدقق","تأكيد مطلق"],["Risk before controls","Only residual risk after all controls","Auditor cost","Absolute assurance"],0,"الخطر الملازم يتعلق بطبيعة النشاط قبل الرقابة؛ المتبقي بعد الاستجابة شيء آخر، ولا توجد ضمانات مطلقة.","Inherent risk exists before controls; residual risk follows response, and assurance is not absolute."],
  [17,"fraud-risk","su17-risk-controls","hard","شخص واحد يعد المورد ويطلق الدفع ويسوي البنك. أي خطر رئيس وكيف تستجيب؟","One person creates vendors, pays them and reconciles the bank. Identify the main risk and response.",["دفع لمورد وهمي؛ فصل الواجبات ومراجعة مستقلة","نقص مبيعات؛ زيادة السعر","تأخر تدريب؛ إلغاء الرواتب","لا خطر ما دام النظام آليًا"],["Fictitious-vendor payment; segregation and independent review","Low sales; raise price","Training delay; remove payroll","No risk if computerized"],0,"تجمع السلطات يتيح التحويل وإخفاءه؛ الفصل والتسوية المستقلة يقللان الخطر. الأتمتة وحدها لا تفصل السلطة.","Combined powers allow diversion and concealment; separation and independent reconciliation mitigate risk. Automation alone does not separate authority."],
  [17,"reasonable-assurance","su17-risk-controls","intermediate","لماذا لا توفر الرقابة الداخلية تأكيدًا مطلقًا؟","Why does internal control provide reasonable rather than absolute assurance?",["بسبب التواطؤ والتجاوز والخطأ البشري والتكلفة","لأنها لا تخص التقارير","لأن المجلس غير مسؤول مطلقًا","لأن كل مخاطر البيانات صفر"],["Collusion, override, human error and cost constraints","It excludes reporting","Board has no oversight","All data risk is zero"],0,"حتى نظام جيد قد يُتجاوز أو يتواطأ عليه موظفون؛ توازن تكلفة الرقابة مع المنفعة. الخيارات الأخرى تنكر أهدافها.","Even sound controls can be overridden or defeated by collusion; cost-benefit limits apply. Other options deny control objectives."],

  [18,"control-preventive","su18-control-procedures","easy","أي ضابط وقائي قبل حدوث صرف غير مصرح به؟","Which is a preventive control before unauthorized payment occurs?",["اعتماد مستقل للدفع","تسوية بنك لاحقة","مراجعة خسارة بعد عام","تحليل شكوى بعد الصرف"],["Independent payment authorization","Later bank reconciliation","Review loss next year","Complaint review after payment"],0,"التفويض المستقل يمنع الإطلاق غير المعتمد؛ التسوية والتحليلات اللاحقة كاشفة بعد وقوعه.","Independent authorization blocks release; subsequent reconciliation and reviews are detective."],
  [18,"control-detective","su18-control-procedures","easy","أي إجراء يكشف دفعة مكررة بعد ترحيلها؟","Which procedure detects a duplicate payment after posting?",["تسوية بنك وسجل استثناءات مستقل","تأجيل فحص البنك","توحيد كل الصلاحيات","إلغاء معرف الفاتورة"],["Independent bank reconciliation and exception log","Delay review","Combine permissions","Delete invoice ID"],0,"المطابقة المستقلة وتحليل الاستثناءات يكشفان التكرار؛ الخيارات الأخرى تضعف الأثر الرقابي.","Independent reconciliation and exception review reveal duplication; the other choices weaken detection."],
  [18,"three-way-match","su18-control-procedures","intermediate","قبل الدفع، ما مستندات المطابقة الثلاثية؟","Which three records are matched before vendor payment?",["طلب شراء واستلام وفاتورة","ميزانية ودفتر وخطة","فاتورة وشيك وإعلان","عقد عمل وحضور وراتب"],["Purchase order, receiving report, invoice","Budget, ledger, plan","Invoice, check, advertisement","Employment contract, timecard, payroll"],0,"المطابقة تثبت اعتماد الطلب ووصول البضاعة ومطالبة المورد؛ البقية لا تغطي سلسلة الشراء.","The three records support authorized ordering, receipt and billing; the others are unrelated to this purchasing control."],
  [18,"small-team-compensate","su18-control-procedures","hard","فريق صغير لا يستطيع فصل كل المهام. ما الضابط التعويضي الأنسب؟","A small team cannot fully segregate duties. Which compensating control is strongest?",["مراجعة مستقلة موثقة لتغييرات المورد وكشف البنك","ترك مستخدم واحد بلا مراجعة","إخفاء السجلات","موافقة لفظية بلا أثر"],["Documented independent review of vendor changes and bank activity","Leave one user unchecked","Hide logs","Verbal unrecorded approval"],0,"المراجعة المستقلة القابلة للاختبار تخفف الجمع بين الصلاحيات؛ غياب الأثر أو الإخفاء لا يخفف الخطر.","Testable independent review mitigates combined authority; undocumented or hidden actions do not."],

  [18,"batch-reject","su18-systems-security","hard","دفعة50 فاتورة بمجموع80,000؛ قُبل49 بمبلغ78,000. كم قيمة السجل المرفوض؟","A batch of 50 invoices totals 80,000; 49 accepted total 78,000. What value was rejected?",["2,000","49","78,000","158,000"],["2,000","49","78,000","158,000"],0,"العدد الناقص1 والمبلغ80,000−78,000=2,000؛ 49 عدد مقبول، والبقية لا تمثل الرفض.","One record is missing; 80,000−78,000=2,000. Forty-nine is accepted count, not rejected value."],
  [18,"input-validation","su18-systems-security","intermediate","حقل رقم الفاتورة يمنع التكرار ويتحقق من صيغة التاريخ قبل المعالجة. أي نوع رقابة؟","Invoice ID rejects duplicates and date formats are validated before processing. What control type?",["رقابة إدخال تطبيقية","رقابة مخرجات فقط","نسخ احتياطي","خطة تعافٍ"],["Application input controls","Output-only control","Backup","Recovery plan"],0,"التحقق يحدث عند الإدخال لمنع سجلات غير صالحة؛ النسخ والتعافي يعالجان فقد النظام.","Validation occurs at input to reject invalid records; backup and recovery address system loss."],
  [18,"processing-total","su18-systems-security","hard","ملف إدخال100 سجل وقيمته250,000، والمعالجة قبلت98 بقيمة244,000. أي إجراء يضمن الاكتمال؟","Input has 100 records totaling 250,000; processing accepts 98 worth 244,000. What verifies completeness?",["تسوية سجلين مرفوضين و6,000 قبل إعادة ترحيلهما","إعادة الدفعة كلها بلا تمييز","حذف سجل الرفض","نشر التقرير كما هو"],["Reconcile 2 rejections totaling 6,000 and reprocess only them","Blindly rerun all","Delete rejection log","Publish unchanged"],0,"العدد2 والمبلغ6,000 يجب تعقبها دون تكرار98 المقبولة؛ الخيارات الأخرى تخلق ازدواجًا أو نقصًا مخفيًا.","Two rejected records total 6,000; trace and post just them without duplicating 98 accepted records."],
  [18,"least-privilege","su18-systems-security","intermediate","ما مضمون مبدأ أقل صلاحية في النظام المالي؟","What does least privilege mean in a finance system?",["منح كل دور ما يلزمه فقط مع مراجعة دورية","منح الجميع صلاحية المدير","إلغاء سجلات الوصول","عدم إلغاء حساب المغادر"],["Grant only required rights and review them","Give all admin rights","Remove access logs","Keep leaver accounts"],0,"تقليل الصلاحية يحد من خطأ وتلاعب ويحتاج مراجعة عند تغير الدور؛ البقية ترفع التعرض.","Role-limited reviewed access reduces error and abuse; the alternatives increase exposure."],

  [18,"rpo-backup","su18-continuity","hard","هدف RPO ساعتان والنسخ الوحيد كل24 ساعة. ما التقييم؟","RPO is two hours but backups run every 24 hours only. What is the assessment?",["لا يحقق RPO","يحقق RPO تلقائيًا","RPO يعني زمن عودة الخدمة","النسخ غير مطلوب"],["Does not meet RPO","Automatically meets RPO","RPO is downtime","No backup needed"],0,"قد تفقد الشركة قرابة24 ساعة، لا ساعتين؛ RPO عمر أحدث نسخة مستعادة، وRTO زمن عودة التشغيل.","Nearly 24 hours can be lost; RPO limits data age, whereas RTO concerns service restoration time."],
  [18,"rto-meaning","su18-continuity","intermediate","ما الذي يحدده RTO أربع ساعات؟","What does a four-hour RTO specify?",["هدف أقصى انقطاع للخدمة","أقصى عمر للبيانات المفقودة","سعر نقل البيانات","عدد نسخ السنة"],["Target maximum service downtime","Maximum data-loss window","Data transfer price","Annual backup count"],0,"RTO يقيس زمن استعادة الخدمة؛ فقد البيانات يعبر عنه RPO. البقية مقاييس لا علاقة لها بالاستمرارية.","RTO targets service recovery time; RPO measures data loss. Other choices are unrelated."],
  [18,"continuity-priority","su18-continuity","intermediate","أي نشاط يحدد ترتيب عودة نظام الدفع والأنظمة الأقل حساسية؟","What establishes priority for restoring payments ahead of less critical systems?",["تحليل أثر الأعمال","رأي مورد النسخ وحده","لون لوحة التحكم","تاريخ آخر فاتورة فقط"],["Business impact analysis","Backup vendor preference alone","Dashboard color","Last invoice date alone"],0,"تحليل أثر التوقف يربط العمليات الحرجة بالخسائر والوقت المقبول؛ باقي المعايير لا تقيس أثر الانقطاع.","Business impact analysis maps critical processes to downtime and loss; other choices do not assess interruption cost."],
  [18,"restore-test","su18-continuity","hard","توجد نسخ مشفرة لكن لم تُجرَّب الاستعادة؛ ما الإجراء المهني؟","Encrypted backups exist but restore was never tested. What should be done?",["اختبار استعادة فعلي ضمن RTO مع فحص سلامة البيانات","الاكتفاء بوجود الملف","حذف النسخ القديمة فورًا بلا سياسة","تعطيل سجلات الاختبار"],["Run end-to-end restore within RTO and verify data integrity","Assume file existence is enough","Purge all older copies without policy","Disable test logs"],0,"توفر الملف لا يثبت عمله أو عودة التطبيق والمستخدمين؛ اختبار الاسترجاع والتحقق يكشف العطل قبل الكارثة.","File existence does not prove application recovery or data integrity; timed end-to-end restore tests reveal failure before an incident."],

  [19,"ais-subsystem","su19-accounting-systems","easy","أي نظام يعالج المعاملات الروتينية كوحدة كاملة قبل التقرير؟","Which component processes routine events atomically before reporting?",["TPS","لوحة استثمار فقط","عرض تقديمي","سياسة احتفاظ"],["TPS","Investment dashboard only","Slide deck","Retention policy"],0,"TPS يسجل حدثًا منفصلًا ويضمن اكتمال المعاملة؛ العناصر الأخرى مخرجات أو سياسة لا معالج معاملات.","TPS processes discrete transactions as complete units; the others are outputs or governance policies."],
  [19,"warehouse-mart","su19-accounting-systems","intermediate","مخزن تحليل يغطي المالية والمبيعات والمخزون؛ نسخة مختصة بالمبيعات فقط. ما الثانية؟","An analytical warehouse spans finance, sales and stock; a sales-focused subset is what?",["Data mart","TPS","دفتر مساعد","RTO"],["Data mart","TPS","Subledger","RTO"],0,"Data mart نطاق موضوعي من البيانات التحليلية، أما TPS تشغيلي وRTO مدة تعافٍ.","A data mart focuses on a subject; TPS is operational, and RTO concerns recovery time."],
  [19,"erp-atomic","su19-accounting-systems","hard","بيع آجل رُحل إيراده دون الذمم وبضاعة المخزون؛ ما الخاصية المنتهكة؟","A credit sale posts revenue but omits receivables and inventory effects. Which processing property fails?",["ذرية المعاملة واتساقها","زيادة الأرشفة","التنبؤ الموسمي","تدوير الموظفين"],["Transaction atomicity/consistency","More archiving","Seasonal prediction","Job rotation"],0,"يجب أن تنجح قيود الحدث أو تفشل كوحدة وتبقى الحسابات متسقة؛ البدائل لا تعالج ترحيلًا جزئيًا.","The event must commit or fail as a unit with consistent records; other options do not address partial posting."],
  [19,"warehouse-gap","su19-accounting-systems","hard","سجل ERP عدد1,000 بقيمة500,000 والمخزن990 بقيمة496,000. ما الفارق؟","ERP has 1,000 records totaling 500,000 and warehouse has 990 totaling 496,000. Find gaps.",["10 و4,000","10 و496,000","990 و4,000","1,000 و500,000"],["10 and 4,000","10 and 496,000","990 and 4,000","1,000 and 500,000"],0,"العدد1,000−990=10 والقيمة500,000−496,000=4,000؛ بقية الخيارات تعيد أحد الرصيدين لا فرقًا.","Record gap 10 and amount gap 4,000; others repeat a balance rather than a difference."],

  [19,"gross-net","su19-data-governance","hard","طلبات إجمالية220,000 شاملة مرتجعات20,000 والدفتر صافي200,000. ما أول تفسير للفارق؟","Gross orders are 220,000 including returns of 20,000; the ledger has net 200,000. What should be checked first?",["تعريف الإجمالي والصافي وفترة القياس","ترحيل20,000 إيراد إضافي فورًا","حذف المرتجعات من المصدر","إيقاف المصالحة"],["Align gross/net definitions and period","Post 20,000 extra revenue immediately","Delete source returns","Stop reconciliation"],0,"220,000−20,000=200,000؛ قد يكون الفارق تعريفًا لا خطأ. لا تُغير قيدًا دون التحقق من السلالة والفترة.","220,000−20,000=200,000, so definitions may explain the difference. Do not change entries before checking lineage and period."],
  [19,"data-owner","su19-data-governance","intermediate","من يعتمد تعريف «عميل نشط» ويحل تعارضه بين فرق العمل؟","Who approves the meaning of 'active customer' across teams?",["مالك/مسؤول بيانات محدد ضمن الحوكمة","أي مستعمل عابر","مورد الشبكة وحده","المدقق الخارجي بدل الإدارة"],["Assigned data owner/steward","Any transient user","Network vendor alone","External auditor instead of management"],0,"تحتاج البيانات مالك تعريف وتصحيح؛ المستخدم والمورد لا يملكان قرار معنى الأعمال تلقائيًا.","A named owner or steward governs definitions and corrections; users and vendors do not automatically own business meaning."],
  [19,"retention-hold","su19-data-governance","hard","انتهت مدة الحفظ المعتادة لسجلات لكنها تحت تعليق قانوني قائم. ما الإجراء؟","Records reach normal retention end but remain under a valid legal hold. What should be done?",["استمرار حفظها وحمايتها حتى رفع التعليق","حذفها فورًا","نشرها للجميع","تعطيل سجل الوصول"],["Retain and protect until hold is lifted","Delete immediately","Publish to all","Disable access log"],0,"التعليق يمنع إتلاف السجل حتى ينتهي وفق السياسة المطبقة؛ لا يبيح نشر البيانات أو إخفاء الوصول.","The hold overrides routine disposal until released under applicable policy; it does not justify open access."],
  [19,"quality-timely","su19-data-governance","intermediate","تقرير مبيعات كامل ودقيق لكنه يتأخر ثلاثة أشهر عن قرار أسبوعي. أي بعد جودة متأثر؟","Sales data are complete and accurate but arrive three months after a weekly decision. Which data-quality dimension fails?",["التوقيت","الاكتمال","الدقة العددية","تنوع التنسيق"],["Timeliness","Completeness","Numeric accuracy","Format variety"],0,"قدم البيانات يضعف فائدتها للقرار رغم دقتها واكتمالها؛ الخيارات الأخرى صفات مختلفة.","Late data lose decision value despite accuracy and completeness; other choices describe different qualities."],

  [19,"coso-data-reconcile","su19-coso-data","hard","أرسل النظام 800,000 إلى المخزن، وظهر 792,000 بسبب سجلات مرفوضة. ما إجراء نشاط الرقابة؟","Source sends 800,000 to warehouse but reports 792,000 due to rejected records. Which control activity responds?",["مصالحة مجاميع وسجل استثناء وإعادة معالجة الناقص","الاكتفاء بلوحة النتائج","حذف المصدر","تغيير الاسم فقط"],["Control-total reconciliation, exception log and targeted reprocess","Accept dashboard","Delete source","Rename report"],0,"الفارق8,000 يجب تتبعه وتسجيل حله؛ إعادة الناقص فقط تمنع الازدواج. الخيارات لا تعالج اكتمال التقرير.","Trace the 8,000 gap and document its resolution; targeted reprocessing avoids duplication. Other choices ignore completeness."],
  [19,"coso-data-environment","su19-coso-data","intermediate","تعين المنشأة مالكًا لجودة البيانات وتدرب الفريق وتحدد المسؤولية. أي مكون COSO يعكس ذلك؟","The firm assigns data-quality ownership, trains staff and sets accountability. Which COSO component is foremost?",["بيئة الرقابة","حساب ROI","موازنة نقدية","فرق حجم مبيعات"],["Control environment","ROI calculation","Cash budget","Sales-volume variance"],0,"ثقافة النزاهة والكفاءة والمسؤولية تنتمي لبيئة الرقابة؛ البقية ليست مكونات COSO.","Integrity, competence and accountability are control-environment matters; the alternatives are other accounting tools."],
  [19,"coso-data-monitor","su19-coso-data","intermediate","تراجع الإدارة شهريًا نسبة التحميلات المرفوضة وتتابع معالجة التكرار. أي مكون ظاهر أساسًا؟","Management reviews rejected-load rates monthly and tracks recurring fixes. Which component is chiefly evident?",["المتابعة","إصدار أسهم","تسعير تحويل","استهلاك أصل"],["Monitoring","Equity issuance","Transfer pricing","Depreciation"],0,"التقييم المستمر لعمل الضوابط وتصحيح ضعفها هو متابعة؛ أنشطة المطابقة قد تعمل ضمنه لكنها ليست الوصف الأساسي هنا.","Ongoing evaluation and remediation of controls is monitoring; the other actions are unrelated."],
  [19,"coso-data-access","su19-coso-data","hard","محلل يكتب في جدول العميل الأصلي ويعدل تقرير الإيراد بلا اعتماد. أي معالجة تقلل الخطر مباشرة؟","An analyst edits source customers and final revenue report without approval. Which response most directly reduces risk?",["تقييد الكتابة وفصل الاعتماد وسجل تغيير","زيادة لون الرسم","حذف المجاميع","تأجيل التسوية"],["Restrict writes, separate approval and log changes","Change chart color","Delete totals","Delay reconciliation"],0,"تحكم الصلاحية والتغيير مع فصل الأدوار يمنع تعديلًا غير معتمد؛ البقية لا تعالج مصدر الخطر.","Access and change control with segregation prevent unapproved edits; the others do not address the root risk."],
  [20,"rpa-hours","su20-finance-transformation","hard","6,000 فاتورة سنويًا تستغرق4 دقائق يدويًا ودقيقة مراجعة بعد الأتمتة. كم ساعة توفر؟","6,000 invoices yearly take four minutes manually and one review minute after automation. How many hours are saved?",["100","300","400","600"],["100","300","400","600"],1,"6,000×(4−1)÷60=300 ساعة؛ 400 وقت يدوي كامل، و100 وقت المراجعة بعد الأتمتة.","6,000×3/60=300 saved hours; 400 is all manual time and 100 is remaining review time."],
  [20,"rpa-net","su20-finance-transformation","hard","توفير300 ساعة بسعر30 وتكلفة روبوت سنوية5,000. ما الوفر الصافي السنوي قبل تكلفة التطوير الأولية؟","Saved 300 hours at 30/hour, with annual bot cost 5,000. Find annual net saving before initial development.",["4,000","5,000","9,000","14,000"],["4,000","5,000","9,000","14,000"],0,"وفر الأجور9,000 ناقص تكلفة سنوية5,000=4,000؛ 9,000 إجمالي و14,000 يجمع نفقة بدل طرحها.","Labor saving 9,000 less bot cost 5,000 gives 4,000; 9,000 is gross, while 14,000 wrongly adds cost."],
  [20,"sdlc-acceptance","su20-finance-transformation","intermediate","ما اختبار قبول مالي مهم قبل نشر نظام فواتير جديد؟","Which finance acceptance test matters before launching a new invoice system?",["ربط القيود والمجاميع ومعالجة التكرار والرفض","شكل الشعار وحده","عدد أسطر الشيفرة","إلغاء توثيق الاستثناءات"],["Reconcile postings/totals and test duplicates/rejections","Logo alone","Line count","Remove exception documentation"],0,"تثبت المصالحة والسيناريوهات السليمة والخاطئة صحة المعالجة؛ المظهر أو طول الكود لا يكفيان.","Reconciliations and valid/invalid scenarios test processing integrity; visual design or code length alone does not."],
  [20,"cloud-responsibility","su20-finance-transformation","intermediate","بعد نقل النظام إلى السحاب، من يتابع صلاحيات مستخدمي المحاسبة وتصنيف البيانات؟","After a cloud migration, who must oversee finance-user access and data classification?",["إدارة المنشأة مع المورد وفق تقاسم المسؤولية","المورد وحده بلا مراجعة","المستخدم النهائي وحده","لا أحد"],["Entity management with the provider under shared responsibility","Provider alone unchecked","End user alone","Nobody"],0,"تظل المنشأة مسؤولة عن حوكمة مستخدميها وبياناتها ولو استضاف المورد البنية؛ البقية تسقط الرقابة.","The entity retains responsibility for its users and data even when a provider hosts infrastructure; the other choices abandon oversight."],

  [20,"analytics-types","su20-data-analytics","intermediate","تقرير يصف مبيعات الأمس، نموذج يتوقع الغد، ونظام يقترح كمية الشراء. ما الترتيب؟","A report describes yesterday's sales, a model estimates tomorrow's, and a system recommends order quantity. Name the sequence.",["وصفي، تنبؤي، توجيهي","توجيهي، وصفي، تنبؤي","تنبؤي، توجيهي، وصفي","جميعها وصفية"],["Descriptive, predictive, prescriptive","Prescriptive, descriptive, predictive","Predictive, prescriptive, descriptive","All descriptive"],0,"ما حدث وصفي، ما قد يحدث تنبؤي، وأفضل فعل ضمن قيود توجيهي؛ البدائل تعكس الوظائف.","What happened is descriptive, what may happen predictive, and a recommended action prescriptive."],
  [20,"pareto-70","su20-data-analytics","hard","تكرارات أسباب العيب A=40 وB=30 وC=20 وD=10. كم حصة أول سببين؟","Defect counts A=40, B=30, C=20 and D=10. What is the top two's share?",["30%","40%","70%","100%"],["30%","40%","70%","100%"],2,"(40+30)÷100=70%؛ 30% يخص B وحده، و40% يخص A، و100% يشمل كل الأسباب.","(40+30)/100=70%; 40% and 30% are individual shares, 100% all causes."],
  [20,"simple-rsquared","su20-data-analytics","hard","في انحدار خطي بسيط مع ثابت r=−0.6. ما R² والتفسير الصحيح؟","For a simple linear regression with an intercept, r=−0.6. What is R² and its meaning?",["36% من تباين العينة مفسر بالخط","60% احتمال صحة كل توقع","−36% تباين مفسر","36% إثبات سببية"],["36% of sample variation explained by the line","60% chance each forecast is right","−36% explained variation","36% proof of causation"],0,"(−0.6)²=0.36. لا يساوي احتمال نجاح تنبؤ فردي ولا يثبت علاقة سببية؛ R² ليس سالبًا هنا.","(−0.6)²=0.36; this is neither individual forecast probability nor proof of causation, and R² is nonnegative."],
  [20,"chart-choice","su20-data-analytics","intermediate","أي رسم أنسب لتتبع المبيعات شهرًا بعد شهر، وأي رسم لترتيب أسباب العيب تنازليًا؟","Which displays suit monthly sales over time and ranked defect causes, respectively?",["خط زمني ثم باريتو","دائرة ثم مبعثر","باريتو ثم خط زمني","مبعثر ثم دائرة"],["Line chart then Pareto","Pie then scatter","Pareto then line chart","Scatter then pie"],0,"الخط يُظهر الاتجاه الزمني وباريتو يبرز أهم الفئات ونسبتها التراكمية؛ البدائل لا تطابق السؤالين.","A line shows a time trend; Pareto orders categorical causes with cumulative share. The others mismatch the questions."],
];

export const CMA_QUESTIONS_UNITS_15_20 = rows.flatMap(([unit, ...spec]) =>
  makeCmaQuestions(unit, [spec]),
);
